// ts-01 完整示例：类型只活在编译期，值与值之间才是运行时
// 运行方式：npx tsx ts-01.ts；或先 npx tsc 再 node 运行编译产物
// 注意：tsc 会把类型注解与 interface 全部擦除，运行时只剩普通 JS

// 1) 结构类型：形状对了就能赋值，名字不参与判断
interface Point { x: number; y: number }
const p = { x: 1, y: 2, z: 3 }
const point: Point = p // 变量赋值不做多余属性检查
// const bad: Point = { x: 1, y: 2, z: 3 } // 新鲜字面量会被检查：z 不存在
console.log(point.x + point.y) // 3

// 2) 推断与宽化：let 宽化成 string，对象属性同样被宽化
let a = 'dark' // string
const b = 'dark' // 'dark'
const conf = { theme: 'dark' } // { theme: string }
console.log(a, b, conf.theme) // dark dark dark

// 3) as const：readonly + 保留字面量，深层生效，但运行时没有冻结
const confConst = { theme: 'dark' } as const // { readonly theme: 'dark' }
type Mode = (typeof confConst)['theme'] | 'light'

// 4) satisfies：检查形状，但不改变推断结果
const palette = {
  light: '#fff',
  dark: '#000',
} satisfies Record<Mode, string>
console.log(palette.dark) // #000

// 5) unknown：能接住任何值，用之前必须收窄
function describe(v: unknown): string {
  if (typeof v === 'string') return `字符串，长度 ${v.length}`
  if (Array.isArray(v)) return `数组，长度 ${v.length}`
  if (v instanceof Date) return `日期 ${v.toISOString()}`
  return `其他：${String(v)}`
}
console.log(describe('abc'), describe([1, 2]), describe(42))
// 字符串，长度 3 数组，长度 2 其他：42

// 6) never：空集，用来证明分支已经穷尽
function unreachable(x: never): never {
  throw new Error(`未处理的状态：${JSON.stringify(x)}`)
}
type Status = 'idle' | 'done'
function label(s: Status): string {
  switch (s) {
    case 'idle': return '等待'
    case 'done': return '完成'
    default: return unreachable(s) // 新增成员而漏写分支时，这一行报错
  }
}
console.log(label('idle'), label('done')) // 等待 完成

// 7) 运行时没有类型：interface 被擦除，只能靠值判断
function isPointLike(v: unknown): v is Point {
  return typeof v === 'object' && v !== null && 'x' in v && 'y' in v
}
console.log(isPointLike(p), isPointLike({ x: 1 })) // true false

// 8) as const 不冻结对象：运行时键仍然只有 theme
console.log(Object.keys(confConst)) // [ 'theme' ]
confConst as { theme: string } // 断言只是让编译器换个看法，不产生任何代码

// ts-02 完整示例：用可辨识联合让非法状态写不出来
// 运行方式：npx tsx ts-02.ts；类型在运行时已被擦除

type User = { id: string; name: string }

// 1) 三个成员各自只带自己需要的字段，判别式 status 是字面量
type LoadState =
  | { status: 'loading' }
  | { status: 'success'; data: User }
  | { status: 'error'; message: string }

// 2) switch 按 status 收窄，每个分支里能安全访问对应字段
function render(s: LoadState): string {
  switch (s.status) {
    case 'loading':
      return '加载中'
    case 'success':
      return `你好，${s.data.name}`
    case 'error':
      return `出错：${s.message}`
  }
}

// 3) 穷尽检查：新增成员而漏写分支时，编译期报错
function assertNever(x: never): never {
  throw new Error(`未处理：${JSON.stringify(x)}`)
}
function renderSafe(s: LoadState): string {
  if (s.status === 'loading') return '加载中'
  if (s.status === 'success') return `你好，${s.data.name}`
  if (s.status === 'error') return `出错：${s.message}`
  return assertNever(s)
}

console.log(render({ status: 'success', data: { id: '1', name: 'ann' } })) // 你好，ann
console.log(renderSafe({ status: 'error', message: '超时' })) // 出错：超时

// 4) 非法状态写不出来：下面两行都会编译报错
// const a: LoadState = { status: 'loading', data: { id: '1', name: 'ann' } }
// const b: LoadState = { status: 'success' }

// 5) 可选属性：缺失与显式 undefined 在序列化时不同
type Patch = { name?: string; age?: number }
const clearName: Patch = { name: undefined }
const empty: Patch = {}
console.log(JSON.stringify(clearName), JSON.stringify(empty)) // {} {}
console.log('name' in clearName, 'name' in empty) // true false

// 6) 断言不是转换：as 不改值，也不检查字段
const raw = JSON.parse('{ "id": "9" }') as User
console.log(raw.id, raw.name) // 9 undefined

// 7) 构造新状态用展开覆盖，编译器会检查结果形状
const failed: LoadState = { status: 'error', message: '网络断开' }
console.log(render(failed)) // 出错：网络断开

