// ts-03 完整示例：泛型把输入和输出的类型绑在一起
// 运行方式：npx tsx ts-03.ts；编译后类型全部擦除，只剩普通函数

type Order = { id: string; amount: number; customer: string }

// 1) 类型参数同时出现在入参和返回值，推断把两者绑定
function first<T>(arr: T[]): T | undefined {
  return arr[0]
}
console.log(first([1, 2, 3])) // 1，T 推断为 number
console.log(first<Order>([])) // undefined，显式指定 T 也能编译
console.log(first(['a'])) // a

// 2) K extends keyof T：键必须存在，返回值跟着键走
function pluck<T, K extends keyof T>(rows: T[], key: K): T[K][] {
  return rows.map(row => row[key])
}
const orders: Order[] = [
  { id: 'a1', amount: 10, customer: 'ann' },
  { id: 'a2', amount: 20, customer: 'bob' },
]
console.log(pluck(orders, 'amount')) // [ 10, 20 ]，类型是 number[]
console.log(pluck(orders, 'customer')) // [ 'ann', 'bob' ]
// console.log(pluck(orders, 'nmae')) // 报错：nmae 不在 keyof Order 里

// 3) 工厂函数：T 从实参推断，后续操作被约束在同一个 T 上
function createStore<T>(initial: T) {
  let state = initial
  return {
    get: (): T => state,
    set: (patch: Partial<T>) => { state = { ...state, ...patch } },
  }
}
const store = createStore({ count: 0, name: 'counter' })
store.set({ count: 1 })
console.log(store.get()) // { count: 1, name: 'counter' }
// store.set({ nmae: 'x' }) // 报错：nmae 不是 Partial 的键

// 4) 默认类型参数：推断优先，推不出来时才用默认值
function listOf<T = string>(item: T, times: number): T[] {
  return Array.from({ length: times }, () => item)
}
console.log(listOf('x', 3)) // [ 'x', 'x', 'x' ]
console.log(listOf(7, 2)) // [ 7, 7 ]，T 推断为 number

// 5) 约束保留信息：有约束才能安全访问成员
function idsOf<T extends { id: string }>(rows: T[]): string[] {
  return rows.map(row => row.id) // 没有约束时 row.id 会报错
}
console.log(idsOf(orders)) // [ 'a1', 'a2' ]

// 6) 两个类型参数协作：键约束防止拼写错误
function indexBy<T, K extends keyof T>(rows: T[], key: K): Record<string, T> {
  const out: Record<string, T> = {}
  for (const row of rows) out[String(row[key])] = row
  return out
}
console.log(Object.keys(indexBy(orders, 'id'))) // [ 'a1', 'a2' ]

// 7) 运行时没有 T：擦除之后 first 就是一个普通函数
console.log(first.name, typeof first) // first function

