// 运行方式：本文件类型擦除后可直接用 node 运行（运行时逻辑与类型无关）。
// 类型检查：npx tsc --noEmit --strict ts-04.ts

type User = {
  id: string
  name: string
  email: string
  password: string
  createdAt: Date
}

// 1) 手写 Partial / Required / Readonly：三者的差别只在修饰符
type MyPartial<T> = { [K in keyof T]?: T[K] }
type MyRequired<T> = { [K in keyof T]-?: T[K] }
type MyReadonly<T> = { readonly [K in keyof T]: T[K] }

// 2) Pick / Omit / Record 都建立在 keyof 与 Exclude 上
type MyPick<T, K extends keyof T> = { [P in K]: T[P] }
type MyOmit<T, K extends keyof any> = MyPick<T, Exclude<keyof T, K>>
type MyRecord<K extends keyof any, V> = { [P in K]: V }

// 3) 运行时：pick 得自己搬数据，类型不会替你复制属性
function pick<T extends object, K extends keyof T>(obj: T, keys: readonly K[]): Pick<T, K> {
  const out: Partial<T> = {}
  for (const key of keys) out[key] = obj[key]
  return out as Pick<T, K> // keys 已限定范围，断言在此是安全的
}

// pick 只搬指定的字段，返回类型同步收窄
const demo = pick({ a: 1, b: 2, c: 3 }, ['a', 'c'])
console.log(demo) // { a: 1, c: 3 }

// 4) 运行时：omit 用剩余键，Set 去重，Object.entries 只取自有可枚举属性
function omit<T extends object, K extends keyof T>(obj: T, keys: readonly K[]): Omit<T, K> {
  const drop = new Set<PropertyKey>(keys)
  const rest = Object.entries(obj).filter(([k]) => !drop.has(k))
  return Object.fromEntries(rest) as Omit<T, K>
}

const user: User = {
  id: 'u_1',
  name: 'ada',
  email: 'ada@example.com',
  password: 's3cret',
  createdAt: new Date('2024-01-01'),
}

// 5) 对外字段：password 不出现，其余字段一个不少
type PublicUser = Omit<User, 'password'>
const publicUser: PublicUser = omit(user, ['password'])
console.log(Object.keys(publicUser)) // [ 'id', 'name', 'email', 'createdAt' ]
console.log('password' in publicUser) // false

// 6) 更新入参：全部可选，但 id 与 createdAt 不允许改
type UserPatch = Partial<Omit<User, 'id' | 'createdAt'>>
const patch: UserPatch = { name: 'ada lovelace' }
console.log(patch) // { name: 'ada lovelace' }
// patch.id = 'u_2' // 编译错误：Property 'id' does not exist on type 'UserPatch'

// 7) Record 把状态映射成配置表：漏一个键就报 Property 'archived' is missing
type Status = 'draft' | 'published' | 'archived'
const label: Record<Status, string> = {
  draft: '草稿',
  published: '已发布',
  archived: '已归档',
}
console.log(label.published) // 已发布

// 8) Omit 的键不受 keyof T 约束：拼错不报错，password 原样保留
type Typo = Omit<User, 'passwrod'>
const typo: Typo = user
console.log(Object.keys(typo).length) // 5

// 9) 浅层语义：Partial 只松开第一层
const nested: MyPartial<{ theme: { color: string } }> = { theme: { color: 'red' } }
console.log(nested.theme?.color) // red

