// 运行方式：类型擦除后 node 直接运行；类型检查用 npx tsc --noEmit --strict。

type User = {
  id: string
  name: string
  age?: number
}

// 1) 自定义守卫：返回类型 v is User 是给编译器的承诺
function isUser(v: unknown): v is User {
  if (typeof v !== 'object' || v === null) return false // 先排 null，再谈属性
  const u = v as Record<string, unknown> // unknown 不能直接取属性，先落成字典
  return (
    typeof u.id === 'string' &&
    u.id.length > 0 &&
    typeof u.name === 'string' &&
    (u.age === undefined || typeof u.age === 'number')
  )
}

// 2) 断言函数：失败就抛，成功后同一作用域直接收窄
function assertUser(v: unknown): asserts v is User {
  if (!isUser(v)) throw new TypeError('not a user')
}

// 3) 批量解析：数组必须单独判断，typeof [] 也是 'object'
function parseUsers(input: unknown): { users: User[]; skipped: number } {
  if (!Array.isArray(input)) throw new TypeError('expect an array')
  const users: User[] = []
  let skipped = 0
  for (const item of input) {
    if (isUser(item)) users.push(item)
    else skipped++
  }
  return { users, skipped }
}

const raw: unknown = [
  null,
  { id: '1', name: 'ada' },
  { id: '' },
  [],
  { id: '2', name: 'bob', age: '30' },
]

const { users, skipped } = parseUsers(raw)
console.log(users) // [ { id: '1', name: 'ada' } ]
console.log(skipped) // 4

// 4) 断言之后，unknown 被收窄成 User
const maybe: unknown = { id: '7', name: 'grace' }
try {
  assertUser(maybe)
  console.log(maybe.name.toUpperCase()) // GRACE
} catch (err) {
  console.log(err instanceof Error ? err.message : String(err))
}

// 5) catch 变量默认是 unknown，必须自己判断类型
try {
  JSON.parse('{oops}')
} catch (err) {
  if (err instanceof SyntaxError) console.log('syntax:', err.message)
  else console.log('unknown error')
}

// 6) 收窄不跨函数边界：const 能保留，let + 回调不能
const stable: User | null = { id: '9', name: 'lin' }
if (stable !== null) {
  setTimeout(() => console.log(stable.name), 0) // OK：const 不会被重新赋值
}

let mutable: User | null = { id: '10', name: 'mo' }
if (mutable !== null) {
  setTimeout(() => console.log(mutable && mutable.name), 0) // 必须重新判空
}

// 7) 守卫写错的代价：只查 id，运行时照样崩
function badIsUser(v: unknown): v is User {
  const u = v as User
  return typeof u.id === 'string'
}
try {
  console.log(badIsUser(null))
} catch (err) {
  console.log(err instanceof TypeError, 'badIsUser(null) 自己先抛错') // true
}

