// 运行方式：类型擦除后 node 可直接运行；类型检查用 npx tsc --noEmit --strict。

// 1) infer：在 extends 右侧捕获类型
type MyReturnType<T> = T extends (...args: any[]) => infer R ? R : never
type MyParameters<T> = T extends (...args: infer P) => any ? P : never

function createUser(name: string, age: number) {
  return { id: `u_${name}`, name, age }
}

type Created = MyReturnType<typeof createUser>
const created: Created = createUser('ada', 30)
console.log(created) // { id: 'u_ada', name: 'ada', age: 30 }

// 2) 递归 + infer：把 Promise 一层层剥开
type MyAwaited<T> = T extends Promise<infer U> ? MyAwaited<U> : T
type Deep = MyAwaited<Promise<Promise<number>>>
const n: Deep = 42
console.log(n) // 42

// 3) 分配律：裸类型参数会把联合拆开
type ToArray<T> = T extends unknown ? T[] : never
type Distributed = ToArray<string | number> // string[] | number[]

type NoDistribute<T> = [T] extends [unknown] ? T[] : never
type Together = NoDistribute<string | number> // (string | number)[]
const both: Together = ['a', 1]
console.log(both) // [ 'a', 1 ]

// 4) 键重映射 + 模板字面量：批量生成 getter 名
type Getters<T> = {
  [K in keyof T & string as `get${Capitalize<K>}`]: () => T[K]
}
type Person = { name: string; age: number }
const personGetters: Getters<Person> = {
  getName: () => 'ada',
  getAge: () => 30,
}
console.log(Object.keys(personGetters)) // [ 'getName', 'getAge' ]

// 5) 键过滤：as 返回 never 的键会被丢掉
type OnlyStrings<T> = {
  [K in keyof T as T[K] extends string ? K : never]: T[K]
}
type Mixed = { id: string; count: number; title: string }
const onlyStrings: OnlyStrings<Mixed> = { id: 'a', title: 'b' }
console.log(onlyStrings) // { id: 'a', title: 'b' }

// 6) 递归映射 + 元组计数器：到第三层就停止展开
type DeepPartial<T, Depth extends readonly unknown[] = []> = Depth['length'] extends 3
  ? T
  : T extends object
    ? { [K in keyof T]?: DeepPartial<T[K], [...Depth, 0]> }
    : T

type Config = { theme: string; editor: { font: { size: number } } }
const partialConfig: DeepPartial<Config> = { editor: { font: {} } }
console.log(partialConfig) // { editor: { font: {} } }

// 7) 运行时不存在类型：上面所有映射与条件判断，编译后一行不剩
console.log(typeof createUser, Object.keys(created)) // function [ 'id', 'name', 'age' ]

