// ts-07｜类型安全的请求层：schema 在边界把关，失败也是类型
// 运行：npx tsx ts-07.ts（Node 18+ / @types/node；不需要网络，transport 是内存实现）
// 预期输出见文件末尾注释

/* ---------- 1. 失败也是类型：四类错误各有各的处理方式 ---------- */
type ApiError =
	| { kind: "network"; message: string }
	| { kind: "timeout"; message: string; timeoutMs: number }
	| { kind: "http"; status: number; message: string; body: unknown }
	| { kind: "parse"; message: string; path: string }

type ApiResult<T> = { ok: true; data: T } | { ok: false; error: ApiError }

/* ---------- 2. schema：运行时唯一能把 unknown 收窄成 T 的东西 ---------- */
class SchemaError extends Error {
	constructor(
		readonly path: string,
		message: string,
	) {
		super(`${path}: ${message}`)
		this.name = "SchemaError"
	}
}

interface Schema<T> {
	parse(input: unknown, path?: string): T
}

const isRecord = (v: unknown): v is Record<string, unknown> =>
	typeof v === "object" && v !== null && !Array.isArray(v)

function asString(v: unknown, path: string): string {
	if (typeof v !== "string") throw new SchemaError(path, `期望 string，实际 ${typeof v}`)
	return v
}

function asNumber(v: unknown, path: string): number {
	if (typeof v !== "number" || Number.isNaN(v)) throw new SchemaError(path, "期望 number")
	return v
}

function asArray(v: unknown, path: string): readonly unknown[] {
	if (!Array.isArray(v)) throw new SchemaError(path, "期望数组")
	return v
}

interface User {
	id: number
	name: string
	email: string | null
	tags: string[]
}

const UserSchema: Schema<User> = {
	parse(input, path = "$") {
		if (!isRecord(input)) throw new SchemaError(path, "期望对象")
		return {
			id: asNumber(input.id, `${path}.id`),
			name: asString(input.name, `${path}.name`),
			// 后端用 null 表示「没有邮箱」，与「字段缺失」是两件事，这里统一收敛成 null
			email:
				input.email === null || input.email === undefined
					? null
					: asString(input.email, `${path}.email`),
			tags: asArray(input.tags, `${path}.tags`).map((t, i) => asString(t, `${path}.tags[${i}]`)),
		}
	},
}

/* ---------- 3. 超时：abort 必须真的发给底层，不只是让上层 reject ---------- */
class TimeoutError extends Error {
	constructor(readonly timeoutMs: number) {
		super(`超时 ${timeoutMs}ms`)
		this.name = "TimeoutError"
	}
}

function withTimeout<T>(run: (signal: AbortSignal) => Promise<T>, timeoutMs: number): Promise<T> {
	const ctrl = new AbortController()
	let timer: ReturnType<typeof setTimeout> | undefined
	const deadline = new Promise<never>((_, reject) => {
		timer = setTimeout(() => {
			ctrl.abort()
			reject(new TimeoutError(timeoutMs))
		}, timeoutMs)
	})
	return Promise.race([run(ctrl.signal), deadline]).finally(() => clearTimeout(timer))
}

/* ---------- 4. 请求：状态码 → 形状 → 业务，一层层判 ---------- */
type Method = "GET" | "POST"

interface RawResponse {
	status: number
	text: string
}

interface TransportRequest {
	url: string
	method: Method
	body?: string
	signal: AbortSignal
}

type Transport = (req: TransportRequest) => Promise<RawResponse>

type Query = Record<string, string | number | boolean | undefined>

interface RequestOptions<T> {
	method?: Method
	query?: Query
	body?: unknown
	readonly schema: Schema<T> // 必填：T 只能由校验产生，不接受「先给我 any，我自己转」
	timeoutMs?: number
	retry?: { times: number; baseDelayMs?: number }
}

function buildSearch(query: Query | undefined): string {
	if (!query) return ""
	const usp = new URLSearchParams()
	for (const [key, value] of Object.entries(query)) {
		if (value !== undefined) usp.set(key, String(value)) // undefined 不进 URL，避免 ?tag=undefined
	}
	const s = usp.toString()
	return s ? `?${s}` : ""
}

const sleep = (ms: number) => new Promise<void>((resolve) => setTimeout(resolve, ms))

function toApiError(err: unknown, timeoutMs: number): ApiError {
	if (err instanceof TimeoutError) return { kind: "timeout", message: err.message, timeoutMs }
	if (err instanceof SchemaError) return { kind: "parse", message: err.message, path: err.path }
	if (err instanceof SyntaxError)
		return { kind: "parse", message: `响应不是合法 JSON：${err.message}`, path: "$" }
	if (err instanceof Error && err.name === "AbortError")
		return { kind: "network", message: "请求被取消" }
	return { kind: "network", message: err instanceof Error ? err.message : String(err) }
}

function isRetryable(error: ApiError): boolean {
	if (error.kind === "timeout" || error.kind === "network") return true
	if (error.kind === "http") return error.status === 429 || error.status >= 500
	return false // parse 错误重试也没用：契约不会因为再请求一次就变对
}

async function request<T>(
	transport: Transport,
	path: string,
	options: RequestOptions<T>,
): Promise<ApiResult<T>> {
	const { method = "GET", schema, timeoutMs = 3000, retry } = options
	const url = path + buildSearch(options.query)
	// 只有幂等请求才允许重试：POST 重放可能重复下单
	const attempts = method === "GET" ? (retry?.times ?? 0) + 1 : 1
	let last: ApiError = { kind: "network", message: "未发出请求" }

	for (let attempt = 0; attempt < attempts; attempt++) {
		const result = await attemptOnce(transport, {
			url,
			method,
			body: options.body === undefined ? undefined : JSON.stringify(options.body),
			schema,
			timeoutMs,
		})
		if (result.ok) return result
		last = result.error
		if (!isRetryable(last) || attempt === attempts - 1) return result
		await sleep((retry?.baseDelayMs ?? 100) * (attempt + 1)) // 递增退避
	}
	return { ok: false, error: last }
}

async function attemptOnce<T>(
	transport: Transport,
	input: { url: string; method: Method; body?: string; schema: Schema<T>; timeoutMs: number },
): Promise<ApiResult<T>> {
	try {
		const res = await withTimeout((signal) => transport({ ...input, signal }), input.timeoutMs)

		// 先判状态码，再判形状：500 的 HTML 错误页不该被报成「schema 写错了」
		if (res.status < 200 || res.status >= 300) {
			let body: unknown = res.text
			try {
				body = JSON.parse(res.text)
			} catch {
				/* 保留原始文本，方便日志里看网关返回了什么 */
			}
			return {
				ok: false,
				error: { kind: "http", status: res.status, message: `HTTP ${res.status}`, body },
			}
		}

		const raw: unknown = res.text === "" ? null : JSON.parse(res.text)
		return { ok: true, data: input.schema.parse(raw) }
	} catch (err) {
		return { ok: false, error: toApiError(err, input.timeoutMs) }
	}
}

/* ---------- 5. mock transport：把四类错误都造出来 ---------- */
let calls = 0

const mock: Transport = async ({ url, signal }) => {
	calls++
	await sleep(5)
	if (signal.aborted) throw Object.assign(new Error("aborted"), { name: "AbortError" })
	if (url.startsWith("/users/1")) {
		return { status: 200, text: JSON.stringify({ id: 1, name: "Ada", email: null, tags: ["ts", "types"] }) }
	}
	if (url.startsWith("/users/2")) {
		return { status: 200, text: JSON.stringify({ id: 2, tags: [] }) } // 后端漏发 name
	}
	if (url.startsWith("/users/3")) {
		return { status: 503, text: "upstream down" } // 网关错误页，不是 JSON
	}
	if (url.startsWith("/slow")) {
		await sleep(300) // 故意比 timeout 长
		return { status: 200, text: '{"id":9,"name":"Slow","email":null,"tags":[]}' }
	}
	return { status: 404, text: JSON.stringify({ code: 404, message: "user not found" }) }
}

async function main() {
	const ok = await request(mock, "/users/1", { schema: UserSchema, query: { page: 1, tag: undefined } })
	console.log("1 成功:", ok.ok ? ok.data.name : ok.error)

	const wrongShape = await request(mock, "/users/2", { schema: UserSchema })
	console.log(
		"2 形状不对:",
		wrongShape.ok ? "不该成功" : `${wrongShape.error.kind} ${"path" in wrongShape.error ? wrongShape.error.path : ""}`,
	)

	const retried = await request(mock, "/users/3", { schema: UserSchema, retry: { times: 2 } })
	console.log("3 重试后:", retried.ok ? "不该成功" : retried.error.kind)

	const timedOut = await request(mock, "/slow", { schema: UserSchema, timeoutMs: 80 })
	console.log("4 超时:", timedOut.ok ? "不该成功" : timedOut.error.kind)

	const notFound = await request(mock, "/users/9", { schema: UserSchema })
	console.log("5 404:", notFound.ok ? "不该成功" : notFound.error.kind)

	console.log("mock 调用次数:", calls)
}

