// ts-08｜tsconfig 体检器：把 extends 合并、strict 展开、开关联动算清楚
// 运行：npx tsx ts-08.ts（只用标准库，无网络、无依赖）
// 预期输出见文件末尾注释

type Scalar = string | number | boolean
type OptionValue = Scalar | string[] | Record<string, string[]>
type Options = Record<string, OptionValue>

interface TsConfigFile {
	extends?: string
	compilerOptions?: Options
	include?: string[]
}

/* ---------- 1. 三份真实世界里会出现的配置 ---------- */
const disk: Record<string, TsConfigFile> = {
	"./tsconfig.base.json": {
		compilerOptions: {
			target: "ES2022",
			lib: ["ES2022", "DOM"],
			strict: true,
			skipLibCheck: true,
			module: "esnext",
			moduleResolution: "bundler",
			noEmit: true,
			outDir: "./dist",
		},
	},
	"./tsconfig.web.json": {
		extends: "./tsconfig.base.json",
		compilerOptions: { jsx: "react-jsx", paths: { "@/*": ["./src/*"] } },
		include: ["src"],
	},
	"./tsconfig.json": {
		extends: "./tsconfig.web.json",
		compilerOptions: { module: "commonjs", verbatimModuleSyntax: true, paths: { "~/*": ["./src/*"] } },
		include: ["src", "scripts"],
	},
	"./tsconfig.legacy.json": {
		extends: "./tsconfig.base.json",
		compilerOptions: { strict: false, strictPropertyInitialization: true },
		include: ["legacy"],
	},
}

/* ---------- 2. 解析 extends：compilerOptions 浅合并，include 整体覆盖 ---------- */
interface Resolved {
	options: Options
	include: string[]
	chain: string[]
}

function load(path: string, seen: string[] = []): Resolved {
	if (seen.includes(path)) throw new Error(`extends 成环：${[...seen, path].join(" -> ")}`)
	const file = disk[path]
	if (!file) throw new Error(`找不到配置文件：${path}`)

	const base: Resolved = file.extends
		? load(file.extends, [...seen, path])
		: { options: {}, include: [], chain: [] }

	return {
		// 浅合并：同名键由子配置覆盖。对象值不会深合并，paths 会被整体换掉
		options: { ...base.options, ...(file.compilerOptions ?? {}) },
		// include 不拼接：子配置写了就整体覆盖父配置的
		include: file.include ?? base.include,
		chain: [...base.chain, path],
	}
}

/* ---------- 3. 展开 strict：单开关显式值优先 ---------- */
const STRICT_FLAGS = [
	"noImplicitAny",
	"strictNullChecks",
	"strictFunctionTypes",
	"strictBindCallApply",
	"strictPropertyInitialization",
	"noImplicitThis",
	"alwaysStrict",
	"useUnknownInCatchVariables",
] as const

type StrictFlag = (typeof STRICT_FLAGS)[number]
type Flags = Record<StrictFlag, boolean>

function expandStrict(options: Options): Flags {
	const strict = options.strict === true
	const flags = {} as Flags
	for (const flag of STRICT_FLAGS) {
		const explicit = options[flag]
		// strict 只是一句默认值；显式写了 false 的开关仍然关着
		flags[flag] = typeof explicit === "boolean" ? explicit : strict
	}
	return flags
}

/* ---------- 4. 联动检查：单个开关合法，组合起来可能不合法 ---------- */
const BUNDLER_MODULES = new Set([
	"es6",
	"es2015",
	"es2016",
	"es2017",
	"es2018",
	"es2019",
	"es2020",
	"es2021",
	"es2022",
	"es2023",
	"esnext",
	"preserve",
])

type Severity = "error" | "warn"

interface Finding {
	severity: Severity
	rule: string
	message: string
}

function lint(resolved: Resolved): Finding[] {
	const { options } = resolved
	const findings: Finding[] = []
	const readText = (key: string) => (typeof options[key] === "string" ? (options[key] as string) : undefined)
	const enabled = (key: string) => options[key] === true
	const flags = expandStrict(options)
	const moduleKind = readText("module")
	const resolution = readText("moduleResolution")

	// R1：bundler 只认 es2015+ 或 preserve，配 commonjs 会被编译器直接拒绝（TS5095）
	if (resolution === "bundler" && (!moduleKind || !BUNDLER_MODULES.has(moduleKind))) {
		findings.push({
			severity: "error",
			rule: "bundler-module",
			message: `moduleResolution=bundler 只能配 module=preserve 或 es2015+，当前 module=${moduleKind ?? "未设"}`,
		})
	}

	// R2：paths 只是编译期的解析规则，tsc 不会重写产出的 import 路径
	if (options.paths !== undefined) {
		findings.push({
			severity: "warn",
			rule: "paths-runtime",
			message: "paths 别名不会写进产物：tsc 产出的 import 仍是 @/lib/x，运行时要么配打包器 alias，要么用 package.json 的 imports",
		})
	}

	// R3：strictPropertyInitialization 依赖 strictNullChecks，单独打开没有意义
	if (flags.strictPropertyInitialization && !flags.strictNullChecks) {
		findings.push({
			severity: "error",
			rule: "spi-needs-nullchecks",
			message: "strictPropertyInitialization 需要 strictNullChecks，否则检查不出未初始化的字段",
		})
	}

	// R4：strict: false 是一键关八个，不是「只关一点点」
	if (options.strict === false) {
		const on = STRICT_FLAGS.filter((flag) => flags[flag])
		findings.push({
			severity: "warn",
			rule: "strict-off",
			message: `strict: false 关掉 ${STRICT_FLAGS.length - on.length}/${STRICT_FLAGS.length} 个开关，只剩 ${on.join("、") || "无"}`,
		})
	}

	// R5：verbatimModuleSyntax 下 ESM 语法不降级，commonjs 文件里写 import/export 直接报错
	if (enabled("verbatimModuleSyntax") && moduleKind === "commonjs") {
		findings.push({
			severity: "warn",
			rule: "verbatim-cjs",
			message: "verbatimModuleSyntax + commonjs：CJS 文件里写 import/export 会报 TS1295/TS1287，两边只能留一个",
		})
	}

	// R6：noEmit 时 outDir 是死配置
	if (enabled("noEmit") && options.outDir !== undefined) {
		findings.push({
			severity: "warn",
			rule: "noemit-outdir",
			message: "noEmit=true 时 outDir 不生效，别以为产物在 ./dist",
		})
	}

	return findings
}

/* ---------- 5. 输出：把「最终生效的配置」打印出来，而不是靠记忆 ---------- */
function report(path: string): void {
	const resolved = load(path)
	const flags = expandStrict(resolved.options)
	console.log(`\n=== ${path} ===`)
	console.log("继承链:", resolved.chain.join(" -> "))
	console.log("include:", JSON.stringify(resolved.include))
	console.log("paths:", JSON.stringify(resolved.options.paths ?? null))
	console.log("module/moduleResolution:", `${resolved.options.module}/${resolved.options.moduleResolution}`)
	console.log("strict 家族:", STRICT_FLAGS.map((f) => `${f}:${flags[f] ? "on" : "off"}`).join("  "))
	const findings = lint(resolved)
	if (findings.length === 0) console.log("未发现问题")
	for (const f of findings) console.log(`[${f.severity}] ${f.rule}: ${f.message}`)
}

report("./tsconfig.json")
report("./tsconfig.legacy.json")

