// ts-12｜运行时校验：类型不是保险箱 —— 一个能收集错误路径的 schema 校验器
// 运行：npx tsx ts-12.ts（只用标准库，无网络、无依赖）
// 预期输出见文件末尾注释

/* ---------- 1. 结果类型：失败是值，不是异常 ---------- */
type Issue = { path: string; message: string }
type Validated<T> = { ok: true; value: T } | { ok: false; issues: Issue[] }

interface Schema<T> {
	parse(input: unknown, path?: string): Validated<T>
}

// 从 schema 推出 TS 类型：类型与校验规则只有一个来源
type Infer<S> = S extends Schema<infer T> ? T : never

function fail(path: string, message: string): Validated<never> {
	return { ok: false, issues: [{ path, message }] }
}

function describe(v: unknown): string {
	if (v === null) return "null"
	if (Array.isArray(v)) return "array"
	return typeof v
}

/* ---------- 2. 基础类型：每个都返回 schema，可以组合 ---------- */
function string(opts: { min?: number; max?: number; pattern?: RegExp } = {}): Schema<string> {
	return {
		parse(input, path = "$") {
			if (typeof input !== "string") return fail(path, `期望 string，实际 ${describe(input)}`)
			if (opts.min !== undefined && input.length < opts.min) return fail(path, `长度不能小于 ${opts.min}`)
			if (opts.max !== undefined && input.length > opts.max) return fail(path, `长度不能大于 ${opts.max}`)
			if (opts.pattern && !opts.pattern.test(input)) return fail(path, "格式不匹配")
			return { ok: true, value: input }
		},
	}
}

function number(opts: { int?: boolean; min?: number; max?: number } = {}): Schema<number> {
	return {
		parse(input, path = "$") {
			if (typeof input !== "number" || Number.isNaN(input))
				return fail(path, `期望 number，实际 ${describe(input)}`)
			if (opts.int && !Number.isInteger(input)) return fail(path, "期望整数")
			if (opts.min !== undefined && input < opts.min) return fail(path, `不能小于 ${opts.min}`)
			if (opts.max !== undefined && input > opts.max) return fail(path, `不能大于 ${opts.max}`)
			return { ok: true, value: input }
		},
	}
}

function literals<L extends readonly string[]>(...values: L): Schema<L[number]> {
	return {
		parse(input, path = "$") {
			if (typeof input === "string" && (values as readonly string[]).includes(input)) {
				return { ok: true, value: input as L[number] }
			}
			return fail(path, `期望其中之一：${values.join(", ")}`)
		},
	}
}

/* ---------- 3. 组合子：nullable / optional / array / object ---------- */
function nullable<T>(inner: Schema<T>): Schema<T | null> {
	return {
		parse(input, path = "$") {
			return input === null ? { ok: true, value: null } : inner.parse(input, path)
		},
	}
}

function optional<T>(inner: Schema<T>): Schema<T | undefined> {
	return {
		parse(input, path = "$") {
			return input === undefined ? { ok: true, value: undefined } : inner.parse(input, path)
		}
	}
}

function array<T>(item: Schema<T>): Schema<T[]> {
	return {
		parse(input, path = "$") {
			if (!Array.isArray(input)) return fail(path, `期望数组，实际 ${describe(input)}`)
			const issues: Issue[] = []
			const value: T[] = []
			input.forEach((el, i) => {
				const r = item.parse(el, `${path}[${i}]`)
				if (r.ok) value.push(r.value)
				else issues.push(...r.issues) // 一个元素坏了，不影响其他元素继续检查
			})
			return issues.length > 0 ? { ok: false, issues } : { ok: true, value }
		},
	}
}

type Shape = Record<string, Schema<unknown>>
type InferShape<S extends Shape> = { [K in keyof S]: Infer<S[K]> }
const isRecord = (v: unknown): v is Record<string, unknown> =>
	typeof v === "object" && v !== null && !Array.isArray(v)

function object<S extends Shape>(
	shape: S,
	opts: { mode?: "strip" | "strict" } = {},
): Schema<InferShape<S>> {
	const mode = opts.mode ?? "strip"
	return {
		parse(input, path = "$") {
			if (!isRecord(input)) return fail(path, `期望对象，实际 ${describe(input)}`)
			const issues: Issue[] = []
			const out: Record<string, unknown> = {}

			for (const key of Object.keys(shape)) {
				const r = shape[key].parse(input[key], `${path}.${key}`)
				if (r.ok) out[key] = r.value
				else issues.push(...r.issues) // 收集全部字段的问题，不在第一个错误处停下
			}

			if (mode === "strict") {
				for (const key of Object.keys(input)) {
					if (!(key in shape)) issues.push({ path: `${path}.${key}`, message: "未知字段" })
				}
			}

			if (issues.length > 0) return { ok: false, issues }
			// 全库唯一一次断言：到这里每个字段都已被逐项验证过
			return { ok: true, value: out as InferShape<S> }
		},
	}
}

/* ---------- 4. 用组合子描述契约，类型自动推出来 ---------- */
const UserSchema = object({
	id: number({ int: true }),
	name: string({ min: 1, max: 20 }),
	email: nullable(string({ pattern: /^[^@\s]+@[^@\s]+$/ })),
	tags: array(string()),
	role: literals("admin", "member"),
})

type User = Infer<typeof UserSchema>
// 鼠标悬停 User：{ id: number; name: string; email: string | null; tags: string[]; role: "admin" | "member" }

const SettingsSchema = object({
	theme: literals("light", "dark"),
	pageSize: optional(number({ int: true, min: 1, max: 100 })),
})

function loadSettings(raw: unknown) {
	const r = SettingsSchema.parse(raw)
	if (!r.ok) {
		// 不抛异常：降级到默认值，但把问题路径原样交回去，让调用方决定上报还是提示
		return { settings: { theme: "light" as const, pageSize: 20 }, issues: r.issues }
	}
	return { settings: r.value, issues: [] as Issue[] }
}

/* ---------- 5. 四组输入，看错误路径长什么样 ---------- */
const messy: unknown = JSON.parse(
	'{"id":1.5,"name":"","email":"not-an-email","tags":["a",2],"role":"guest"}',
)
const good: unknown = { id: 7, name: "Ada", email: null, tags: ["ts"], role: "admin" }
const legacyStorage: unknown = JSON.parse('{"theme":{"name":"dark"}}')

const check = (label: string, r: Validated<unknown>) => {
	if (r.ok) console.log(label, "→", JSON.stringify(r.value))
	else console.log(label, "→", r.issues.map((i) => `${i.path} ${i.message}`).join(" | "))
}

check("1 乱七八糟的对象", UserSchema.parse(messy))
check("2 合法的对象", UserSchema.parse(good))

const strictCheck = object({ id: number() }, { mode: "strict" })
check("3 strict 模式多字段", strictCheck.parse({ id: 1, extra: true }))

const loaded = loadSettings(legacyStorage)
console.log("4 localStorage 旧数据 → 降级:", JSON.stringify(loaded.settings), "| 问题数:", loaded.issues.length)
