// ────────── 坏版本：递归映射，遇到 Date / 函数 / 数组就失真 ──────────
type DeepPartial<T> = { [K in keyof T]?: DeepPartial<T[K]> };

interface User {
  id: string;
  name: string;
  createdAt: Date;
  tags: string[];
  notify: (msg: string) => void;
}

// 下面三行都能通过编译，但语义都是错的：
const emptyDate: DeepPartial<Date> = {};
console.log(emptyDate.getTime);          // 预期输出：undefined（类型说它可选）
const badArray: DeepPartial<string[]> = { 0: "a" };
console.log(badArray.length);            // 预期输出：undefined（数组方法全丢）

declare const u: DeepPartial<User>;
// u.notify?.("hi");                    // 报错：This expression is not callable
u.notify;                                // 类型是 {}，不是函数

// 注意：映射类型只搬属性，不保留调用签名与数组的方法
type Mutable<T> = { -readonly [K in keyof T]: T[K] };  // 只解一层 readonly，安全

type Probe = DeepPartial<User>["createdAt"];
// hover 可见：{ getTime?: ...; getFullYear?: ... } —— 它已经不是 Date 了

export type { Probe, Mutable };

// ────────── 好版本：显式接口 + 只解一层 ──────────
interface UpdateUserInput {
  name?: string;
  tags?: string[];
  notify?: (msg: string) => void;
}

async function updateUser(id: string, patch: UpdateUserInput): Promise<void> {
  await fetch(`/api/users/${id}`, {
    method: "PATCH",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(patch),   // 形状与类型一致：createdAt 根本进不来
  });
}

updateUser("u1", { name: "Ada" });            // 通过
updateUser("u1", { createdAt: new Date() });   // 报错：多余属性，类型里没有 createdAt

